surl --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox carol@example.com:carolpass --shared-folder team=ann@example.com,bob@example.com smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
